export const EXAM_MAX_MISTAKES = 2; // shuncha xatodan keyin imtihon avtomatik tugaydi

// Qo'llab-quvvatlanadigan savol tillari. Tartib LANGUAGES (src/i18n/index.js)
// bilan mos: uz_latn (asosiy), uz_cyrl (avtomatik), ru (qo'lda tarjima).
export const SUPPORTED_QUESTION_LANGS = ["uz_latn", "uz_cyrl", "ru"];

