// Xom (ko'p tilli) savol obyektini berilgan tilga moslab, eski (yagona
// matnli) shaklga o'tkazadi: { id, text, options, correct, image }.
// Agar so'ralgan tilda tarjima bo'lmasa (masalan, ru hali qo'shilmagan
// bilet), uz_latn'ga avtomatik qaytadi — hech qachon bo'sh yoki undefined
// matn ko'rsatilmaydi.
export function localizeQuestion(q, lang = "uz_latn") {
  const text = (q.text && q.text[lang]) || q.text.uz_latn;
  const options = (q.options && q.options[lang]) || q.options.uz_latn;
  return { id: q.id, text, options, correct: q.correct, image: q.image };
}

// Bilet uchun savollarni qaytaradi (berilgan tilda, lokalizatsiya qilingan).
export function getTicketQuestions(ticketNumber, lang = "uz_latn") {
  return (TICKETS[ticketNumber] || []).map((q) => localizeQuestion(q, lang));
}

// Oddiy, tez va deterministik pseudo-random generator (aralashtirish uchun)
function seededRandom(seed) {
  let s = seed % 2147483647;
  if (s <= 0) s += 2147483646;
  return function next() {
    s = (s * 16807) % 2147483647;
    return (s - 1) / 2147483646;
  };
}

function shuffleWithSeed(array, rand) {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// Barcha biletlardagi savollarni yagona ro'yxat sifatida qaytaradi (berilgan tilda).
export function getAllQuestions(lang = "uz_latn") {
  return Object.values(TICKETS).flat().map((q) => localizeQuestion(q, lang));
}

// Imtihon rejimi uchun — har chaqirilganda TASODIFIY savollar
// (barcha bilet bazasidan aralashtirilib, QUESTIONS_PER_TICKET dona, berilgan tilda)
export function getRandomExamQuestions(lang = "uz_latn") {
  const allQuestions = getAllQuestions(lang);
  const rand = Math.random;
  return shuffleWithSeed(allQuestions, rand).slice(0, QUESTIONS_PER_TICKET);
}
